nginx_conf:
# Managed by Aura — do not edit by hand.
upstream checkout_backend {
  least_conn;
  server 10.0.0.1:8080;
  server 10.0.0.2:8080;
  server 10.0.0.3:8080;
}

server {
  listen 443 ssl;
  server_name checkout.example.com;

  ssl_certificate     /etc/ssl/checkout.crt;
  ssl_certificate_key /etc/ssl/checkout.key;

  location / {
    proxy_pass http://checkout_backend;
    proxy_set_header Host checkout.example.com;
  }
}
